class Solution {
public:
    int countHillValley(vector<int>& nums) {
        vector<int> v;
        for (int x : nums) {
            if (v.empty() || v.back() != x) v.push_back(x);
        }
        int ans = 0;
        for (int i = 1; i + 1 < (int)v.size(); i++) {
            if ((v[i] > v[i - 1] && v[i] > v[i + 1]) || (v[i] < v[i - 1] && v[i] < v[i + 1])) {
                ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int countHillValley(int[] nums) {
        List<Integer> v = new ArrayList<>();
        for (int x : nums) {
            if (v.isEmpty() || v.get(v.size() - 1) != x) v.add(x);
        }
        int ans = 0;
        for (int i = 1; i + 1 < v.size(); i++) {
            if ((v.get(i) > v.get(i - 1) && v.get(i) > v.get(i + 1)) ||
                (v.get(i) < v.get(i - 1) && v.get(i) < v.get(i + 1))) {
                ans++;
            }
        }
        return ans;
    }
}

