var countHillValley = function(nums) {
    const v = [nums[0]];
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] !== v[v.length - 1]) v.push(nums[i]);
    }
    let ans = 0;
    for (let i = 1; i + 1 < v.length; i++) {
        if ((v[i] > v[i - 1] && v[i] > v[i + 1]) || (v[i] < v[i - 1] && v[i] < v[i + 1])) {
            ans++;
        }
    }
    return ans;
